package com.tripcraft.config;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.Configuration; import org.springframework.web.servlet.config.annotation.ResourceHandlerRegistry; import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;
@Configuration public class UploadResourceConfig implements WebMvcConfigurer { private final String dir; public UploadResourceConfig(@Value("${app.upload-dir:uploads}")String dir){this.dir=dir;} @Override public void addResourceHandlers(ResourceHandlerRegistry registry){String location="file:"+new java.io.File(dir).getAbsolutePath()+java.io.File.separator;registry.addResourceHandler("/uploads/**").addResourceLocations(location);}}
